/**
 * Arabic joining forms for invoice PDFs.
 * Packed from the Unicode character database (ArabicShaping + presentation-form
 * decompositions). The data is the public Unicode tables, not a third-party shaper.
 */

export type ArabicJoinType = 'D' | 'R' | 'L' | 'U' | 'C' | 'T';

const JOIN_PACKED = "";
const FORM_PACKED = "";

const JOIN = new Map<number, ArabicJoinType>();
for (let i = 0; i < JOIN_PACKED.length; i += 5) {
  JOIN.set(parseInt(JOIN_PACKED.slice(i, i + 4), 16), JOIN_PACKED[i + 4] as ArabicJoinType);
}

type Forms = { isol: number; fina: number; init: number; medi: number };
const FORMS = new Map<number, Forms>();
for (let i = 0; i < FORM_PACKED.length; i += 20) {
  const n = (at: number) => parseInt(FORM_PACKED.slice(i + at, i + at + 4), 16);
  FORMS.set(n(0), { isol: n(4), fina: n(8), init: n(12), medi: n(16) });
}

/** Lam + alef-class ligatures: [isolated, final]. */
const LAM_ALEF: Record<number, [number, number]> = {
  0x0622: [0xFEF5, 0xFEF6],
  0x0623: [0xFEF7, 0xFEF8],
  0x0625: [0xFEF9, 0xFEFA],
  0x0627: [0xFEFB, 0xFEFC],
};

function isTransparent(cp: number): boolean {
  return JOIN.get(cp) === 'T';
}

function joinsTowardPrev(type: ArabicJoinType | undefined): boolean {
  return type === 'D' || type === 'L' || type === 'C';
}

function joinsTowardNext(type: ArabicJoinType | undefined): boolean {
  return type === 'D' || type === 'R' || type === 'C';
}

/** Map Arabic letters to presentation forms so a PDF font can draw them without OpenType shaping. */
export function reshapeArabic(input: string): string {
  if (!input || !/[\u0600-\u08FF]/.test(input)) return input;
  const cps = Array.from(input, (ch) => ch.codePointAt(0) || 0);
  const out: number[] = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    const type = JOIN.get(cp);
    if (!type || type === 'T' || type === 'U') {
      out.push(cp);
      continue;
    }
    let prev: number | null = null;
    let next: number | null = null;
    for (let p = i - 1; p >= 0; p--) {
      if (!isTransparent(cps[p])) {
        prev = cps[p];
        break;
      }
    }
    for (let n = i + 1; n < cps.length; n++) {
      if (!isTransparent(cps[n])) {
        next = cps[n];
        break;
      }
    }
    const prevType = prev == null ? undefined : JOIN.get(prev);
    const nextType = next == null ? undefined : JOIN.get(next);
    const jPrev = joinsTowardPrev(prevType);
    const jNext = joinsTowardNext(nextType);
    if (cp === 0x0644 && next != null && LAM_ALEF[next]) {
      const pair = LAM_ALEF[next];
      out.push(jPrev ? pair[1] : pair[0]);
      i += 1;
      continue;
    }
    const rec = FORMS.get(cp);
    if (!rec) {
      out.push(cp);
      continue;
    }
    if (jPrev && jNext && rec.medi) out.push(rec.medi);
    else if (jPrev && rec.fina) out.push(rec.fina);
    else if (jNext && rec.init) out.push(rec.init);
    else out.push(rec.isol || cp);
  }
  return String.fromCodePoint(...out);
}
